shadow_bundle.shadow_css:
:host { display: block; width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }
.wsj-shadow-body { width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }

  :host {
    --paper: #faf8f4;
    --paper-card: #f3efe6;
    --paper-deep: #eae3d5;
    --ink: #141413;
    --body: #242220;
    --muted: #646059;
    --line: #e4dfd3;
    --line-strong: #c9c1b0;
    --accent: #b85d19;
    --crimson: #9e2a2b;
    --amber: #b45309;
    --navy-bg: #0f1d2b;
    --navy-card: #16283a;
    --navy-line: #294159;
    --teal-corridor: #1e6b65;
  }

  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    background-color: var(--paper);
    color: var(--body);
    font-family: 'Noto Serif SC', 'Lora', Georgia, serif;
    -webkit-font-smoothing: antialiased;
    scroll-behavior: smooth;
  }

  :host([lang="zh-CN"]) .lang-en { display: none !important; }
  :host([lang="en"]) .lang-cn { display: none !important; }

  .wsj-shadow-body {
    overflow-x: hidden;
    background-color: var(--paper);
    background-image: radial-gradient(rgba(20, 20, 19, 0.03) 1px, transparent 0);
    background-size: 24px 24px;
  }

  /* Reading Progress Bar */
  #progress-bar {
    position: fixed;
    top: 0;
    left: 0;
    height: 3px;
    width: 0%;
    background: linear-gradient(90deg, var(--crimson), var(--accent));
    z-index: 1001;
    transition: width 0.1s ease-out;
  }

  /* Sticky Masthead */
  .masthead {
    position: sticky;
    top: 0;
    z-index: 1000;
    background: rgba(250, 248, 244, 0.94);
    backdrop-filter: blur(10px);
    border-bottom: 1px solid var(--line);
    padding: 0.7rem 1.5rem;
  }

  .masthead-inner {
    max-width: 1180px;
    margin: 0 auto;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
  }

  .brand-group {
    display: flex;
    align-items: center;
    gap: 0.85rem;
    flex-wrap: wrap;
  }

  .wsj-logo {
    font-family: 'Playfair Display', serif;
    font-weight: 800;
    font-size: 1.05rem;
    letter-spacing: 0.06em;
    color: var(--ink);
    text-transform: uppercase;
  }

  .masthead-tag {
    font-family: 'JetBrains Mono', monospace;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--crimson);
    background: rgba(158, 42, 43, 0.09);
    border: 1px solid rgba(158, 42, 43, 0.25);
    padding: 0.18rem 0.5rem;
    border-radius: 2px;
    font-weight: 600;
  }

  .lang-switch {
    display: inline-flex;
    border: 1px solid var(--line-strong);
    border-radius: 3px;
    overflow: hidden;
    background: var(--paper-card);
  }

  .lang-btn {
    border: none;
    background: transparent;
    padding: 0.32rem 0.75rem;
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.76rem;
    font-weight: 600;
    color: var(--muted);
    cursor: pointer;
    transition: all 0.2s ease;
  }

  .lang-btn.active {
    background: var(--ink);
    color: var(--paper);
  }

  /* Hero Section */
  .hero {
    max-width: 1180px;
    margin: 0 auto;
    padding: 3.5rem 1.5rem 2.5rem;
    border-bottom: 2px solid var(--ink);
  }

  .hero-kicker-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 0.75rem;
    margin-bottom: 1.25rem;
    padding-bottom: 0.85rem;
    border-bottom: 1px solid var(--line);
  }

  .kicker-label {
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.78rem;
    font-weight: 700;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: var(--crimson);
    display: flex;
    align-items: center;
    gap: 0.5rem;
  }

  .kicker-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: var(--crimson);
    box-shadow: 0 0 0 4px rgba(158, 42, 43, 0.18);
  }

  .dispatch-code {
    font-family: 'JetBrains Mono', monospace;
    font-size: 0.75rem;
    color: var(--muted);
  }

  .hero-title {
    font-family: 'Playfair Display', 'Noto Serif SC', serif;
    font-weight: 800;
    font-size: clamp(2.15rem, 4.4vw, 3.65rem);
    line-height: 1.16;
    color: var(--ink);
    letter-spacing: -0.015em;
    margin-bottom: 1.15rem;
    max-width: 960px;
  }

  :host([lang="zh-CN"]) .hero-title {
    line-height: 1.24;
    letter-spacing: 0.01em;
  }

  .hero-dek {
    font-family: 'Lora', 'Noto Serif SC', serif;
    font-size: clamp(1.12rem, 2vw, 1.42rem);
    line-height: 1.55;
    color: var(--muted);
    max-width: 820px;
    margin-bottom: 1.75rem;
    font-weight: 400;
  }

  .byline-bar {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
    padding-top: 1rem;
    border-top: 1px solid var(--line);
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.82rem;
    color: var(--muted);
  }

  .byline-author strong {
    color: var(--ink);
    font-weight: 700;
    letter-spacing: 0.04em;
  }

  /* Telemetry Strip */
  .telemetry-strip {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 1px;
    background: var(--line-strong);
    border: 1px solid var(--line-strong);
    margin-top: 2rem;
  }

  .telemetry-cell {
    background: var(--paper-card);
    padding: 1.15rem 1.25rem;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
  }

  .telemetry-tag {
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--muted);
    margin-bottom: 0.4rem;
  }

  .telemetry-num {
    font-family: 'Playfair Display', 'JetBrains Mono', serif;
    font-size: 1.85rem;
    font-weight: 800;
    color: var(--ink);
    line-height: 1.1;
    margin-bottom: 0.35rem;
  }

  .telemetry-num.crimson { color: var(--crimson); }
  .telemetry-num.amber { color: var(--amber); }

  .telemetry-desc {
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.78rem;
    line-height: 1.4;
    color: var(--body);
  }

  /* Context Dossier Banner */
  .dossier-wrap {
    max-width: 1180px;
    margin: 2rem auto 0;
    padding: 0 1.5rem;
  }

  .context-dossier {
    background: var(--paper-card);
    border-left: 4px solid var(--navy-bg);
    border-top: 1px solid var(--line);
    border-right: 1px solid var(--line);
    border-bottom: 1px solid var(--line);
    padding: 1.25rem 1.5rem;
    display: grid;
    grid-template-columns: 170px 1fr;
    gap: 1.25rem;
    align-items: start;
  }

  .dossier-badge {
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.74rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.09em;
    color: var(--navy-bg);
    padding-top: 0.15rem;
  }

  .dossier-badge span {
    display: block;
    font-size: 0.68rem;
    color: var(--muted);
    font-weight: 400;
    margin-top: 0.25rem;
  }

  .dossier-text {
    font-family: 'Noto Sans SC', 'Inter', sans-serif;
    font-size: 0.92rem;
    line-height: 1.72;
    color: var(--body);
  }

  /* Main Editorial Grid */
  .editorial-container {
    max-width: 1180px;
    margin: 0 auto;
    padding: 2.75rem 1.5rem 4rem;
  }

  .act-section {
    margin-bottom: 3.75rem;
  }

  .act-header {
    display: flex;
    align-items: baseline;
    gap: 0.85rem;
    margin-bottom: 1.75rem;
    padding-bottom: 0.65rem;
    border-bottom: 1px solid var(--ink);
  }

  .act-index {
    font-family: 'JetBrains Mono', monospace;
    font-size: 0.78rem;
    font-weight: 700;
    color: var(--crimson);
    letter-spacing: 0.1em;
    text-transform: uppercase;
  }

  .act-title {
    font-family: 'Playfair Display', 'Noto Serif SC', serif;
    font-size: 1.35rem;
    font-weight: 700;
    color: var(--ink);
  }

  .asymmetric-rail {
    display: grid;
    grid-template-columns: minmax(0, 680px) minmax(260px, 380px);
    justify-content: space-between;
    gap: 3rem;
    align-items: start;
  }

  /* Prose Styling */
  .prose-col {
    max-width: 680px;
  }

  .prose-p {
    font-size: 1.125rem;
    line-height: 1.9;
    color: var(--body);
    margin-bottom: 1.55rem;
  }

  :host([lang="en"]) .prose-p {
    font-family: 'Lora', Georgia, serif;
    font-size: 1.12rem;
    line-height: 1.82;
  }

  /* Lead paragraph treatment without ::first-letter on Chinese */
  .prose-p.lead-para {
    font-size: 1.24rem;
    line-height: 1.85;
    color: var(--ink);
    font-weight: 600;
    padding-left: 1.15rem;
    border-left: 3px solid var(--crimson);
    margin-bottom: 1.85rem;
  }

  /* Inline Highlight */
  mark.ed-hl {
    background: linear-gradient(180deg, transparent 58%, rgba(184, 93, 25, 0.22) 58%);
    color: inherit;
    padding: 0 0.12em;
    font-weight: 600;
  }

  /* Sidebar Dossier & Callouts */
  .rail-aside {
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
    position: sticky;
    top: 4.5rem;
  }

  .forensic-card {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-top: 3px solid var(--crimson);
    padding: 1.35rem;
  }

  .forensic-card.amber-top {
    border-top-color: var(--amber);
  }

  .forensic-header {
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.73rem;
    font-weight: 700;
    letter-spacing: 0.09em;
    text-transform: uppercase;
    color: var(--crimson);
    margin-bottom: 0.85rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
  }

  .forensic-card.amber-top .forensic-header {
    color: var(--amber);
  }

  .forensic-title {
    font-family: 'Playfair Display', 'Noto Serif SC', serif;
    font-size: 1.08rem;
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 0.85rem;
    line-height: 1.35;
  }

  .incident-log {
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.83rem;
    line-height: 1.5;
  }

  .incident-log li {
    padding-bottom: 0.75rem;
    border-bottom: 1px dashed var(--line-strong);
    display: grid;
    grid-template-columns: 76px 1fr;
    gap: 0.65rem;
  }

  .incident-log li:last-child {
    border-bottom: none;
    padding-bottom: 0;
  }

  .log-key {
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.72rem;
    font-weight: 700;
    color: var(--muted);
    text-transform: uppercase;
  }

  .log-val {
    color: var(--ink);
  }

  /* Sovereign Advisory Matrix */
  .advisory-tier {
    margin-top: 0.65rem;
    padding: 0.75rem;
    background: var(--paper);
    border: 1px solid var(--line);
  }

  .tier-badge {
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.68rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    display: inline-block;
    padding: 0.12rem 0.45rem;
    margin-bottom: 0.4rem;
  }

  .tier-badge.avoid {
    background: rgba(180, 83, 9, 0.14);
    color: var(--amber);
  }

  .tier-badge.overflight {
    background: rgba(158, 42, 43, 0.14);
    color: var(--crimson);
  }

  .tier-countries {
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.85rem;
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 0.2rem;
  }

  .tier-desc {
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.78rem;
    color: var(--muted);
    line-height: 1.45;
  }

  /* Derived Pull Quote */
  .pull-quote {
    background: var(--navy-bg);
    color: var(--paper);
    padding: 1.5rem 1.4rem;
    border-left: 4px solid var(--accent);
    position: relative;
  }

  .pull-quote::before {
    content: "“";
    font-family: 'Playfair Display', serif;
    font-size: 3.4rem;
    line-height: 1;
    color: rgba(250, 248, 244, 0.16);
    position: absolute;
    top: 0.5rem;
    right: 1rem;
  }

  .quote-text {
    font-family: 'Noto Serif SC', 'Playfair Display', serif;
    font-size: 1.08rem;
    font-weight: 600;
    line-height: 1.65;
    margin-bottom: 0.85rem;
    color: #fff;
  }

  .quote-attrib {
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.74rem;
    color: #b7c6d6;
    letter-spacing: 0.04em;
  }

  /* Theater Ledger Matrix (Act II) */
  .theater-ledger {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 1.5rem;
    margin: 2rem 0;
  }

  .ledger-head {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    flex-wrap: wrap;
    gap: 0.5rem;
    border-bottom: 2px solid var(--ink);
    padding-bottom: 0.75rem;
    margin-bottom: 1.25rem;
  }

  .ledger-title {
    font-family: 'Playfair Display', 'Noto Serif SC', serif;
    font-size: 1.18rem;
    font-weight: 700;
    color: var(--ink);
  }

  .ledger-sub {
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.72rem;
    color: var(--muted);
    text-transform: uppercase;
  }

  .ledger-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 1rem;
  }

  .ledger-col {
    background: var(--paper);
    border: 1px solid var(--line);
    padding: 1.1rem;
    display: flex;
    flex-direction: column;
    gap: 0.55rem;
  }

  .ledger-date {
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.71rem;
    font-weight: 700;
    color: var(--crimson);
    text-transform: uppercase;
    letter-spacing: 0.06em;
  }

  .ledger-hub {
    font-family: 'Noto Serif SC', 'Playfair Display', serif;
    font-size: 1rem;
    font-weight: 700;
    color: var(--ink);
  }

  .ledger-detail {
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.82rem;
    line-height: 1.55;
    color: var(--body);
  }

  /* Full-Bleed Strategic SVG Map Container */
  .map-showcase {
    background: var(--navy-bg);
    color: var(--paper);
    border: 1px solid var(--navy-line);
    padding: 2rem 1.75rem;
    margin: 2.5rem 0;
    box-shadow: 0 14px 34px rgba(15, 29, 43, 0.14);
  }

  .map-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    flex-wrap: wrap;
    gap: 1rem;
    margin-bottom: 1.35rem;
    padding-bottom: 1rem;
    border-bottom: 1px solid var(--navy-line);
  }

  .map-kicker {
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #f59e0b;
    margin-bottom: 0.35rem;
  }

  .map-title {
    font-family: 'Playfair Display', 'Noto Serif SC', serif;
    font-size: 1.45rem;
    font-weight: 700;
    color: #ffffff;
    margin-bottom: 0.35rem;
  }

  .map-subtitle {
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.86rem;
    color: #b4c4d4;
    max-width: 680px;
    line-height: 1.5;
  }

  .map-legend {
    display: flex;
    flex-wrap: wrap;
    gap: 1rem;
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.76rem;
    color: #cbd5e1;
  }

  .legend-item {
    display: flex;
    align-items: center;
    gap: 0.45rem;
  }

  .legend-swatch {
    width: 18px;
    height: 3px;
    display: inline-block;
  }

  .svg-wrapper {
    width: 100%;
    overflow: hidden;
    background: #0b1622;
    border: 1px solid var(--navy-line);
    border-radius: 2px;
  }

  .svg-wrapper svg {
    display: block;
    width: 100%;
    height: auto;
  }

  .map-footnotes {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 1rem;
    margin-top: 1.35rem;
    padding-top: 1.15rem;
    border-top: 1px solid var(--navy-line);
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.8rem;
    line-height: 1.5;
    color: #cbd5e1;
  }

  .map-fn-item strong {
    display: block;
    color: #fff;
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.74rem;
    margin-bottom: 0.25rem;
    text-transform: uppercase;
  }

  /* Carrier Routing Comparison Cards (Act III) */
  .carrier-cards {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1.25rem;
    margin-top: 1.75rem;
  }

  .carrier-box {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 1.25rem;
  }

  .carrier-name {
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.78rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.07em;
    color: var(--accent);
    margin-bottom: 0.4rem;
  }

  .carrier-route {
    font-family: 'Playfair Display', 'Noto Serif SC', serif;
    font-size: 1.05rem;
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 0.65rem;
  }

  .carrier-shift {
    font-family: 'Inter', 'Noto Sans SC', sans-serif;
    font-size: 0.83rem;
    line-height: 1.55;
    color: var(--body);
  }

  /* Footer */
  .ed-footer {
    max-width: 1180px;
    margin: 0 auto;
    padding: 2rem 1.5rem 4rem;
    border-top: 2px solid var(--ink);
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 1rem;
    font-family: 'JetBrains Mono', 'Noto Sans SC', monospace;
    font-size: 0.75rem;
    color: var(--muted);
  }

  /* Responsive Mobile Reflow */
  @media (max-width: 920px) {
    .asymmetric-rail {
      grid-template-columns: 1fr;
      gap: 2rem;
    }
    .rail-aside {
      position: static;
    }
    .telemetry-strip {
      grid-template-columns: repeat(2, 1fr);
    }
    .ledger-grid,
    .map-footnotes,
    .carrier-cards {
      grid-template-columns: 1fr;
    }
    .context-dossier {
      grid-template-columns: 1fr;
      gap: 0.6rem;
    }
  }

  @media (max-width: 520px) {
    .masthead {
      padding: 0.6rem 1rem;
    }
    .hero {
      padding: 2.25rem 1rem 1.75rem;
    }
    .dossier-wrap,
    .editorial-container,
    .ed-footer {
      padding-left: 1rem;
      padding-right: 1rem;
    }
    .telemetry-strip {
      grid-template-columns: 1fr;
    }
    .map-showcase {
      padding: 1.25rem 1rem;
    }
  }
